import{_ as e,c as a,o as i,b0 as l}from"./chunks/framework.Becqh7-x.js";const s="/linux-dev-docs/assets/Busybox-800x400.DHt70JUO.jpg",n="/linux-dev-docs/assets/image-20241128074042740.D7uQ0UcB.png",r="/linux-dev-docs/assets/image-20241128074313793.Dq6tTALD.png",d="/linux-dev-docs/assets/image-20241128074453329.DxDEn_r7.png",m=JSON.parse('{"title":"LV100-busybox简介","description":null,"frontmatter":{"title":"LV100-busybox简介","date":"2026-01-13T09:37:35.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/img/rootfs/126d2cd814672063e0124429","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-13T09:37:35.518Z","fulluuid":"3e0124429fc34d259300ca7ae2a44b3c","useduuid":null}},"headers":[],"relativePath":"sdoc/img/rootfs/126d2cd814672063e0124429.md","filePath":"sdoc/15-系统镜像/30-rootfs/LV100-busybox简介.md","lastUpdated":1768604092000}'),o={name:"sdoc/img/rootfs/126d2cd814672063e0124429.md"};function u(c,t,p,b,h,g){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lv100-busybox简介" tabindex="-1">LV100-busybox简介 <a class="header-anchor" href="#lv100-busybox简介" aria-label="Permalink to &quot;LV100-busybox简介&quot;">​</a></h1><h2 id="一、busybox-简介" tabindex="-1">一、busybox 简介 <a class="header-anchor" href="#一、busybox-简介" aria-label="Permalink to &quot;一、busybox 简介&quot;">​</a></h2><h3 id="_1-busybox-是什么" tabindex="-1">1. busybox 是什么 <a class="header-anchor" href="#_1-busybox-是什么" aria-label="Permalink to &quot;1. busybox 是什么&quot;">​</a></h3><img src="'+s+'" alt="img" style="zoom:50%;"><p>官网的简介是这样写的：<a href="https://www.busybox.net/about.html" target="_blank" rel="noreferrer">BusyBox - about</a></p><blockquote><p><strong>BusyBox: The Swiss Army Knife of Embedded Linux</strong></p><p>BusyBox combines tiny versions of many common UNIX utilities into a single small executable. It provides replacements for most of the utilities you usually find in GNU fileutils, shellutils, etc. The utilities in BusyBox generally have fewer options than their full-featured GNU cousins; however, the options that are included provide the expected functionality and behave very much like their GNU counterparts. BusyBox provides a fairly complete environment for any small or embedded system.</p><p>BusyBox has been written with size-optimization and limited resources in mind. It is also extremely modular so you can easily include or exclude commands (or features) at compile time. This makes it easy to customize your embedded systems. To create a working system, just add some device nodes in /dev, a few configuration files in /etc, and a Linux kernel.</p><p>BusyBox is maintained by <a href="mailto:vda.linux@googlemail.com" target="_blank" rel="noreferrer">Denys Vlasenko</a>, and licensed under the <a href="https://www.busybox.net/license.html" target="_blank" rel="noreferrer">GNU GENERAL PUBLIC LICENSE</a> version 2</p></blockquote><p>简单来说 busybox 是一个开源的、轻量级的软件工具集合，旨在提供一个精简的 Unix 工具集，适用于嵌入式系统和资源受限的环境。它将许多常用的 Unix 工具（如 ls、cp、cat、mv、grep、find、telnet 等）合并为一个可执行文件，从而减少了系统的存储空间和资源占用。</p><h3 id="_2-发展历史" tabindex="-1">2. 发展历史 <a class="header-anchor" href="#_2-发展历史" aria-label="Permalink to &quot;2. 发展历史&quot;">​</a></h3><p>GNU Coreutils + Bash 的组合一直是各大 Linux 发行版中的“黄金搭档”，如今几乎所有的 Linux 发行版默认都会使用它们作为默认的 Shell 和基础工具包，Coreutils 包含了一系列每个 Linux 用户都再熟悉不过的命令：ls、cat、grep...几乎所有我们熟悉的“开箱即用”的 Linux 工具都是 Coreutils 的一部分。</p><p>不过在桌面发行版中广受欢迎的它却在嵌入式开发中遇到了一个问题，一个永恒的、经典的问题：成本，或者换句话来说，体积。Coreutils 丰富功能的代价之一就是体积的膨胀，这使得它不适用于嵌入式环境这种对体积要求极为严苛的环境，于是 BusyBox 应运而生。</p><p>BusyBox 做的最关键的一件事就是：压缩体积，它在诞生之初便是为了塞进一张软盘而设计的（当时流行的 3.5 寸软盘容量约为 1.44 MB），这样它既可以作为当时流行的 Debian 系统的急救盘、也可以成为它的安装盘，BusyBox 把原来数十个乃至数百个程序实现的功能塞进了一个可执行文件中，这种高度的集成带来的是体积的极致压缩，因为这样做它便不会受到多个 ELF 文件中冗余文件头的影响，同时多个功能也可以调用同一个库中的代码，进一步压缩了体积。1996 年，初版 BusyBox 诞生了，之后便被广泛应用在各种嵌入式项目和精简发行版中，成为了嵌入式操作系统的事实标准之一，不只是 Linux，FreeBSD 等项目中也不乏 BusyBox 的身影。</p><h3 id="_2-特点" tabindex="-1">2. 特点 <a class="header-anchor" href="#_2-特点" aria-label="Permalink to &quot;2. 特点&quot;">​</a></h3><ul><li><p>精简：Busybox 的设计理念是将多个工具合并为一个可执行文件，从而减少了系统的存储空间和资源占用。</p></li><li><p>可定制性：Busybox 提供了许多编译选项，可以根据需求选择需要的工具，并排除不需要的工具，从而进一步减小可执行文件的大小。</p></li><li><p>兼容性：Busybox 的工具与传统的 Unix 工具具有相似的命令行接口和功能，因此可以方便地替代传统的 Unix 工具。</p></li></ul><h2 id="二、参考资料" tabindex="-1">二、参考资料 <a class="header-anchor" href="#二、参考资料" aria-label="Permalink to &quot;二、参考资料&quot;">​</a></h2><p>busybox 的官网在这里：<a href="https://www.busybox.net/" target="_blank" rel="noreferrer">BusyBox</a>。我们可以在这里找到官方的帮助文档以及源码的下载链接。</p><h2 id="三、源码获取" tabindex="-1">三、源码获取 <a class="header-anchor" href="#三、源码获取" aria-label="Permalink to &quot;三、源码获取&quot;">​</a></h2><h3 id="_1-源码下载" tabindex="-1">1. 源码下载 <a class="header-anchor" href="#_1-源码下载" aria-label="Permalink to &quot;1. 源码下载&quot;">​</a></h3><p>我们可以在这里下载：<a href="https://www.busybox.net/downloads/" target="_blank" rel="noreferrer">Index of /downloads</a>。我下载的是 busybox-1.22.1.tar.bz2 这个压缩包并将其存放于 ubuntu 下的共享文件夹下：</p><img src="'+n+'" alt="image-20241128074042740" style="zoom:67%;"><p>下载的时候可能会非常慢，要是特别慢的话，有条件的可以科学处理一下，哈哈。也可以通过这个命令下载：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.busybox.net/downloads/busybox-1.36.1.tar.bz2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+r+`" alt="image-20241128074313793"><blockquote><p>或者也可以来这里拉取：<a href="https://git.busybox.net/busybox/" target="_blank" rel="noreferrer">busybox - BusyBox: The Swiss Army Knife of Embedded Linux</a></p></blockquote><h3 id="_2-拷贝解压" tabindex="-1">2. 拷贝解压 <a class="header-anchor" href="#_2-拷贝解压" aria-label="Permalink to &quot;2. 拷贝解压&quot;">​</a></h3><p>然后我们可以将这个源码文件拷贝解压到 ubuntu 中，方便后边编译，我们可以在终端执行以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/7Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> busybox-1.36.1.tar.bz2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 解压</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>然后我们可以得到下边这些文件（通过 ls 命令查看）：</p><img src="`+d+'" alt="image-20241128074453329"><h3 id="_3-目录说明" tabindex="-1">3. 目录说明 <a class="header-anchor" href="#_3-目录说明" aria-label="Permalink to &quot;3. 目录说明&quot;">​</a></h3><p>一些目录的说明如下：</p><table><tbody><tr><td align="center" width="220px"> 目录名称 </td> <td align="center"> 功能说明 </td></tr><tr><td align="center"> applets </td> <td align="left"> 实现 applets 框架的文件。目录中包含了几个 main()的文件 </td></tr><tr><td align="center"> applets_sh </td> <td align="left"> 此目录包含了几个作为 shell 脚本实现的 applet 示例。在“make install”时不会被自动安装，需要使用时，手动处理 </td></tr><tr><td align="center"> arch </td> <td align="left"> 包含用于不同体系架构的 makefile 文件。约束 busybox 在不同架构体系下的编译构建过程 </td></tr><tr><td align="center"> archival </td> <td align="left"> 与压缩相关命令的实现源文件。</td></tr><tr><td align="center"> configs </td> <td align="left"> busybox 自带的默认配置文件 </td></tr><tr><td align="center"> console-tools </td> <td align="left"> 与控制台相关的一些命令 </td></tr><tr><td align="center"> coreutils </td> <td align="left"> 常用的一些核心命令。例如 chgrp、rm 等 </td></tr><tr><td align="center"> debianutils </td> <td align="left"> 针对 Debian 的套件。</td></tr><tr><td align="center"> e2fsprogs </td> <td align="left"> 针对 Linux Ext2 FS prog 的命令。例如 chattr、lsattr </td></tr><tr><td align="center"> editors </td> <td align="left"> 常用的编辑命令。例如 diff、vi 等 </td></tr><tr><td align="center"> findutils </td> <td align="left"> 用于查找的命令 </td></tr><tr><td align="center"> include </td> <td align="left"> busybox 项目的头文件 </td></tr><tr><td align="center"> init </td> <td align="left"> init 进程的实现源码目录 </td></tr><tr><td align="center"> klibc-utils </td> <td align="left"> klibc 命令套件 </td></tr><tr><td align="center"> libbb </td> <td align="left"> 与 busybox 实现相关的库文件 </td></tr><tr><td align="center"> libpwdgrp </td> <td align="left"> libpwdgrp 相关的命令 </td></tr><tr><td align="center"> loginutils </td> <td align="left"> 与用户管理相关的命令 </td></tr><tr><td align="center"> mailutils </td> <td align="left"> 与 mail 相关的命令套件 </td></tr><tr><td align="center"> miscutils </td> <td align="left"> 该文件下是一些杂项命令，针对特定应用场景 </td></tr><tr><td align="center"> modutils </td> <td align="left"> 与模块相关的命令 </td></tr><tr><td align="center"> networking </td> <td align="left"> 与网络相关的命令，例如 arp </td></tr><tr><td align="center"> printutils </td> <td align="left"> Print 相关的命令 </td></tr><tr><td align="center"> procps </td> <td align="left"> 与内存、进程相关的命令 </td></tr><tr><td align="center"> runit </td> <td align="left"> 与 Runit 实现相关的命令 </td></tr><tr><td align="center"> shell </td> <td align="left"> 与 shell 相关的命令 </td></tr><tr><td align="center"> sysklogd </td> <td align="left"> 系统日志记录工具相关的命令 </td></tr><tr><td align="center"> util-linux </td> <td align="left"> Linux 下常用的命令，主要与文件系统操作相关的命令。</td></tr></tbody></table><blockquote><p>参考资料</p><p><a href="https://linuxstory.org/busybox-swiss-knife-of-embedded-linux/" target="_blank" rel="noreferrer">嵌入式 Linux 的瑞士军刀：BusyBox - LinuxStory</a></p><p><a href="https://zh.wikipedia.org/wiki/BusyBox" target="_blank" rel="noreferrer">BusyBox - 维基百科，自由的百科全书</a></p><p><a href="https://blog.csdn.net/iriczhao/article/details/127308538" target="_blank" rel="noreferrer">【Busybox】Busybox 源码分析-01 | 源码目录结构和程序入口-CSDN 博客</a></p></blockquote>',32)])])}const f=e(o,[["render",u]]);export{m as __pageData,f as default};
